#include <bits/stdc++.h>
using namespace std;
int par[2005],rnk[2005];
int find(int x){return par[x]==x?x:par[x]=find(par[x]);}
void unite(int a,int b){a=find(a);b=find(b);if(a==b)return;if(rnk[a]<rnk[b])swap(a,b);par[b]=a;if(rnk[a]==rnk[b])rnk[a]++;}
int main(){
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int N,K;
    cin>>N>>K;
    int tot=N+K;
    vector<int> id(tot);
    vector<double> x(tot),y(tot);
    vector<char> tp(tot);
    vector<int> robots,relays;
    for(int i=0;i<tot;i++){
        cin>>id[i]>>x[i]>>y[i]>>tp[i];
        if(tp[i]=='C') relays.push_back(i);
        else robots.push_back(i);
    }
    struct Edge{double d;int u,v;};
    vector<Edge> edges;
    for(int i=0;i<tot;i++) for(int j=i+1;j<tot;j++){
        double dx=x[i]-x[j],dy=y[i]-y[j];
        edges.push_back({dx*dx+dy*dy,i,j});
    }
    sort(edges.begin(),edges.end(),[](const Edge&a,const Edge&b){return a.d<b.d;});
    // Kruskal to find bottleneck spanning tree connecting all robots
    // But we want to minimize bottleneck, so standard Kruskal works - add edges in order until all robots connected
    for(int i=0;i<tot;i++){par[i]=i;rnk[i]=0;}
    vector<Edge> treeEdges;
    for(auto&e:edges){
        if(find(e.u)!=find(e.v)){
            unite(e.u,e.v);
            treeEdges.push_back(e);
        }
        // Check if all robots connected
        bool allConn=true;
        for(int i=1;i<(int)robots.size();i++) if(find(robots[0])!=find(robots[i])){allConn=false;break;}
        if(allConn) break;
    }
    // Now prune: remove edges that don't help connect robots (leaf relays)
    // Build tree, iteratively remove degree-1 relays
    set<int> usedNodes(robots.begin(),robots.end());
    for(auto&e:treeEdges){usedNodes.insert(e.u);usedNodes.insert(e.v);}
    bool changed=true;
    while(changed){
        changed=false;
        map<int,int> deg;
        for(auto&e:treeEdges) if(usedNodes.count(e.u)&&usedNodes.count(e.v)){deg[e.u]++;deg[e.v]++;}
        for(int r:relays) if(usedNodes.count(r)&&deg[r]<=1){usedNodes.erase(r);changed=true;}
    }
    vector<Edge> finalEdges;
    for(auto&e:treeEdges) if(usedNodes.count(e.u)&&usedNodes.count(e.v)) finalEdges.push_back(e);
    set<int> usedRelays;
    for(int r:relays) if(usedNodes.count(r)) usedRelays.insert(r);
    if(usedRelays.empty()) cout<<"#\n";
    else{bool f=true;for(int c:usedRelays){if(!f)cout<<"#";cout<<id[c];f=false;}cout<<"\n";}
    {bool f=true;for(auto&e:finalEdges){if(!f)cout<<"#";cout<<id[e.u]<<"-"<<id[e.v];f=false;}cout<<"\n";}
}
